    <script>
        let appData = null;

        // Utility function to safely get nested values
        function SafeGetValue(obj, path, defaultValue = "N/A") {
            if (!obj || typeof path !== 'string') return defaultValue;
            const keys = path.split('.').flatMap(p => p.includes('[') ? p.replace(/]$/, '').split('[') : p);
            let result = keys.reduce((o, k) => {
                if (o === undefined || o === null) return undefined;
                if (/^\d+$/.test(k) && Array.isArray(o)) return o[parseInt(k)];
                if (typeof o === 'object' && k in o) return o[k];
                return undefined;
            }, obj);
            return result ?? defaultValue;
        }

        // Update progress bars
        function updateProgressBar(barId, value, max = 100) {
            const percentage = Math.min(100, Math.max(0, (value / max) * 100));
            document.getElementById(barId).style.width = `${percentage}%`;
        }

        // Toggle collapsible sections
        function toggleCollapsible(toggleElement) {
            const targetId = toggleElement.dataset.target;
            const content = document.getElementById(targetId);
            const isOpen = toggleElement.classList.toggle('open');

            if (content) {
                content.classList.toggle('open');
                toggleElement.querySelector('span').textContent = isOpen ? '▲' : '▼';
            }
        }

        // Switch between views
        function switchView(viewId) {
            // Hide all content views and deactivate nav items
            document.querySelectorAll('.cosmos-content').forEach(content => {
                content.classList.remove('active');
            });

            document.querySelectorAll('.nav-item').forEach(item => {
                item.classList.remove('active');
            });

            // Activate selected view and nav item
            document.getElementById(`view-${viewId}`).classList.add('active');
            document.querySelector(`.nav-item[data-view="${viewId}"]`).classList.add('active');
        }

        // Render Status View
        function renderStatusView() {
            // World Info
            document.getElementById('world-date').textContent = SafeGetValue(appData, '世界.当前日期[0]');
            document.getElementById('world-time').textContent = SafeGetValue(appData, '世界.当前时间[0]');

            const location = SafeGetValue(appData, '世界.当前地点[0]', {});
            document.getElementById('current-location').textContent =
                `${location.市 || ''}${location.区 || ''} - ${location.详细地点 || ''}`;

            // User Info
            const userMoney = SafeGetValue(appData, '{{user}}.现有资金[0]', 0);
            const userIncome = SafeGetValue(appData, '{{user}}.总收入[0]', 0);
            const userExpense = SafeGetValue(appData, '{{user}}.总支出[0]', 0);
            const userSkill = SafeGetValue(appData, '{{user}}.摄影熟练度[0]', { 等级: 1, 经验: 0 });

            document.getElementById('user-money').textContent = `¥ ${userMoney.toLocaleString()}`;
            document.getElementById('user-income').textContent = `¥ ${userIncome.toLocaleString()}`;
            document.getElementById('user-expense').textContent = `¥ ${userExpense.toLocaleString()}`;
            document.getElementById('user-skill-level').textContent = userSkill.等级;
            document.getElementById('user-skill-exp').textContent = userSkill.经验;
            updateProgressBar('user-skill-bar', userSkill.经验, 100);

            // Character Info - Basic
            const charInfo = SafeGetValue(appData, '林晚星.个人信息[0]', {});
            const charOutfit = SafeGetValue(appData, '林晚星.当前着装[0]', {});
            const charAffection = SafeGetValue(appData, '林晚星.对user的好感度[0]', 0);
            const charThoughts = SafeGetValue(appData, '林晚星.对user的内心想法[0]', '...');
            const charMoney = SafeGetValue(appData, '林晚星.现有资金[0]', 0);
            const charCosExpense = SafeGetValue(appData, '林晚星.总支出_cos[0]', 0);
            const charSkill = SafeGetValue(appData, '林晚星.Cos熟练度[0]', { 等级: 1, 经验: 0 });
            const charCorruption = SafeGetValue(appData, '林晚星.腐蚀度[0]', 0);
            const charCosPlan = SafeGetValue(appData, '林晚星.当前Cosplay计划[0]', {});

            document.getElementById('character-impression').textContent = SafeGetValue(charInfo, '观众印象', 'N/A');
            document.getElementById('affection-value').textContent = charAffection;
            document.getElementById('corruption-value').textContent = charCorruption;
            document.getElementById('char-skill-level').textContent = charSkill.等级;
            document.getElementById('char-skill-exp').textContent = charSkill.经验;
            document.getElementById('char-money').textContent = `¥ ${charMoney.toLocaleString()}`;
            document.getElementById('char-cos-expense').textContent = `¥ ${charCosExpense.toLocaleString()}`;
            document.getElementById('char-thoughts').textContent = `"${charThoughts}"`;

            updateProgressBar('affection-bar', charAffection, 100);
            updateProgressBar('corruption-bar', charCorruption, 100);
            updateProgressBar('char-skill-bar', charSkill.经验, 100);

            // Social Media Stats
            const totalFollowers = SafeGetValue(appData, '林晚星.社交影响力_总[0]', 0);
            const weiboFollowers = SafeGetValue(appData, '林晚星.微博.粉丝数[0]', 0);
            const biliFollowers = SafeGetValue(appData, '林晚星.B站.粉丝数[0]', 0);

            document.getElementById('total-followers').textContent = totalFollowers;
            document.getElementById('weibo-followers').textContent = weiboFollowers;
            document.getElementById('bili-followers').textContent = biliFollowers;
            document.getElementById('fan-count').textContent = totalFollowers;
            document.getElementById('weibo-fans').textContent = weiboFollowers;
            document.getElementById('bili-fans').textContent = biliFollowers;

            // Character Info - Detailed
            document.getElementById('daily-appearance').textContent = SafeGetValue(charInfo, '整体外貌.cos前', 'N/A');
            document.getElementById('cos-appearance').textContent = SafeGetValue(charInfo, '整体外貌.cos后', 'N/A');

            // Outfit
            document.getElementById('outfit-hair').textContent = SafeGetValue(charOutfit, '头发', 'N/A');
            document.getElementById('outfit-accessory').textContent = SafeGetValue(charOutfit, '装饰', 'N/A');
            document.getElementById('outfit-face').textContent = SafeGetValue(charOutfit, '面部', 'N/A');
            document.getElementById('outfit-upper').textContent = SafeGetValue(charOutfit, '胸部', 'N/A');
            document.getElementById('outfit-lower').textContent = SafeGetValue(charOutfit, '腿部', 'N/A');
            document.getElementById('outfit-feet').textContent = SafeGetValue(charOutfit, '足部', 'N/A');

            // Cos Plan
            const planName = SafeGetValue(charCosPlan, '角色名称', '');
            const planSource = SafeGetValue(charCosPlan, '来源作品', '');
            const planProgress = SafeGetValue(charCosPlan, '进度', '无');

            if (planName && planSource) {
                document.getElementById('cos-plan').textContent =
                    `${planName} (${planSource}) - ${planProgress}`;
            } else {
                document.getElementById('cos-plan').textContent = `暂无进行中的计划`;
            }
        }

        // Render WeChat View
        function renderWeChatView() {
            const messagesContainer = document.getElementById('wechat-messages');
            const fanMessages = SafeGetValue(appData, '林晚星.粉丝群消息[0]', []);

            let html = '';
            if (Array.isArray(fanMessages)) {
                fanMessages.forEach(msg => {
                    if (typeof msg !== 'object' || !msg.sender || !msg.text) return;

                    // Generate avatar with first character of sender name
                    const seed = encodeURIComponent(msg.sender);
                    const avatarUrl = `https://api.dicebear.com/6.x/micah/svg?seed=${seed}`;

                    html += `
                    <div class="message-bubble">
                        <div class="message-avatar">
                            <img src="${avatarUrl}" alt="${msg.sender}">
                        </div>
                        <div class="message-content">
                            <div class="message-sender">${msg.sender}</div>
                            <div class="message-text">${msg.text}</div>
                        </div>
                    </div>`;
                });
            }

            if (html === '') {
                html = '<div style="padding:20px; text-align:center; color:#a0aec0;">群里现在很安静呢... 💤</div>';
            }

            messagesContainer.innerHTML = html;
        }

        // Render Weibo View
        function renderWeiboView() {
            const postsContainer = document.getElementById('weibo-posts');
            const weiboPosts = SafeGetValue(appData, '林晚星.微博.帖子[0]', []);

            let html = '';
            if (Array.isArray(weiboPosts)) {
                [...weiboPosts].reverse().forEach(post => {
                    if (typeof post !== 'object' || !post.content) return;

                    const timestamp = post.timestamp || '刚刚';
                    const likes = post.likes || 0;
                    const comments = post.comments || 0;
                    const retweets = post.retweets || 0;

                    html += `
                    <div class="weibo-post">
                        <div class="weibo-content">${post.content}</div>
                        ${post.image ? `<img src="${post.image}" alt="Post image" style="width:100%; border-radius:8px; margin:8px 0;">` : ''}
                        <div class="weibo-meta">
                            <div class="meta-item"><i>⏱️</i> ${timestamp}</div>
                            <div class="meta-item"><i>❤️</i> ${likes}</div>
                            <div class="meta-item"><i>💬</i> ${comments}</div>
                            <div class="meta-item"><i>🔄</i> ${retweets}</div>
                        </div>
                    </div>`;
                });
            }

            if (html === '') {
                html = '<div style="padding:20px; text-align:center; color:#a0aec0;">还没有发布任何帖子... 📝</div>';
            }

            postsContainer.innerHTML = html;
        }

        // Render Bilibili View
        function renderBilibiliView() {
            const videosContainer = document.getElementById('bili-videos');
            const biliVideos = SafeGetValue(appData, '林晚星.B站.视频[0]', []);

            let html = '';
            if (Array.isArray(biliVideos)) {
                [...biliVideos].reverse().forEach((video, index) => {
                    if (typeof video !== 'object' || !video.title) return;

                    const views = video.views || '0';
                    const danmaku = video.danmaku || '0';

                    html += `
                    <div class="video-card">
                        <div class="video-thumbnail">
                            <img src="https://picsum.photos/seed/bili${index}/320/180" alt="${video.title}">
                        </div>
                        <div class="video-info">
                            <div class="video-title">${video.title}</div>
                            <div class="video-stats">
                                <span><i>👁️</i> ${views}</span>
                                <span><i>💬</i> ${danmaku}</span>
                            </div>
                        </div>
                    </div>`;
                });
            }

            if (html === '') {
                html = '<div style="padding:20px; text-align:center; color:#a0aec0;">还没有发布任何视频... 🎥</div>';
            }

            videosContainer.innerHTML = html;
        }

        // Initialize the app
        async function initializeApp() {
            try {
                const messages = await getChatMessages(getCurrentMessageId());
                appData = messages?.[0]?.data?.stat_data;

                if (!appData) {
                    document.body.innerHTML = "<p style='color:red; padding: 15px;'>错误: stat_data 未找到。</p>";
                    return;
                }

                // Render all views
                renderStatusView();
                renderWeChatView();
                renderWeiboView();
                renderBilibiliView();

                // Add event listeners
                document.querySelectorAll('.nav-item').forEach(item => {
                    item.addEventListener('click', () => switchView(item.dataset.view));
                });

                document.querySelectorAll('.collapse-toggle').forEach(toggle => {
                    toggle.addEventListener('click', () => toggleCollapsible(toggle));
                });
            } catch (error) {
                document.body.innerHTML = `<p style='color:red; padding: 15px;'>应用加载出错: ${error.message}</p>`;
            }
        }

        // Start the app when DOM is ready
        document.addEventListener('DOMContentLoaded', initializeApp);
    </script>
</body>
</html>
